-- File access rules for the copied Legal files (private legal- buckets, created
-- by the /legal-move copier). Every rule is limited to legal- buckets, so Hair
-- files are never affected. Generated by scripts/legal-move/generate-schema.mjs --storage.
CREATE POLICY "legal_Sales phone no portal files" ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING ((NOT (bucket_id LIKE 'legal-%')) OR (((NOT legal_is_sales_only_user()) OR legal_can_access_portal_page('/training'::text)))) WITH CHECK ((NOT (bucket_id LIKE 'legal-%')) OR ((NOT legal_is_sales_only_user())));
CREATE POLICY "legal_Staff training file scope" ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING ((NOT (bucket_id LIKE 'legal-%')) OR (((bucket_id <> ALL (ARRAY['legal-training-media'::text, 'legal-practice-call-recordings'::text])) OR (NOT legal_has_staff_profile()) OR legal_can_access_portal_page('/training'::text))));
CREATE POLICY "legal_practice recordings read own or admin" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING ((bucket_id LIKE 'legal-%') AND (((bucket_id = 'legal-practice-call-recordings'::text) AND (legal_is_admin_user() OR ((storage.foldername(name))[1] = (auth.uid())::text)))));
CREATE POLICY "legal_training media staff read" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING ((bucket_id LIKE 'legal-%') AND (((bucket_id = 'legal-training-media'::text) AND legal_has_sales_role())));

